#include "stdlib/lapack/base/dpbequ.h"
#include "stdlib/lapack/base/shared.h"
#include <time.h>
#include <math.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
* Main execution sequence.
*/
int main( void ) {
	double AB[ 32 ] = { 0.0 };
	double before[ 32 ];
	double S[ 18 ];
	double sc;
	double am;
	double diagonal;
	LAPACK_INT r;
	LAPACK_INT c;
	LAPACK_INT o;
	LAPACK_INT ss;
	LAPACK_INT os;
	LAPACK_INT info;
	LAPACK_INT N;
	const int32_t sizes[] = { 8, 16 };
	int32_t i;
	int32_t j;
	int32_t upper;
	int32_t failed;
	int32_t nd;
	int32_t repeat;
	int32_t iteration;
	int32_t count = 0;
	double elapsed;
	clock_t t;

	for ( i = 0; i < 2; i++ ) {
		N = sizes[ i ];
		for ( upper = 0; upper < 2; upper++ ) {
			for ( nd = 0; nd < 2; nd++ ) {
				r = nd ? 1 : N;
				c = nd ? -2 : 1;
				o = nd ? 2*(N-1) : 0;
				ss = nd ? -1 : 1;
				os = nd ? N : 0;
				for ( failed = 0; failed < 2; failed++ ) {
					for ( j = 0; j < 2*N; j++ ) {
						AB[ j ] = NAN;
					}
					for ( j = 0; j < N; j++ ) {
						AB[ o+(upper*r)+(j*c) ] = (failed && j == 1) ? -0.0 : (double)((j+2)*(j+2));
					}
					memcpy( before, AB, (size_t)(2*N)*sizeof(double) );
					for ( repeat = 0; repeat < 2; repeat++ ) {
						t = clock();
						for ( iteration = 0; iteration < 200; iteration++ ) {
							for ( j = 0; j < N+2; j++ ) {
								S[ j ] = 7.0;
							}
							sc = -0.0;
							am = -9.0;
							if ( nd ) {
								info = API_SUFFIX(c_dpbequ_ndarray)( upper ? LAPACK_UPPER_TRIANGLE : LAPACK_LOWER_TRIANGLE, N, 1, AB, r, c, o, S, ss, os, &sc, 0, &am, 0 );
							} else {
								info = API_SUFFIX(c_dpbequ)( LAPACK_ROW_MAJOR, upper ? LAPACK_UPPER_TRIANGLE : LAPACK_LOWER_TRIANGLE, N, 1, AB, N, S, &sc, &am );
							}
							if ( info != (failed ? 2 : 0) ) {
								return EXIT_FAILURE;
							}
						}

						elapsed = (double)(clock()-t)/(double)CLOCKS_PER_SEC;
						for ( j = 0; j < N; j++ ) {
							diagonal = AB[ o+(upper*r)+(j*c) ];
							if ( failed ) {
								if ( S[ os+(j*ss) ] != diagonal || (j == 1 && !signbit(S[ os+(j*ss) ])) ) {
									return EXIT_FAILURE;
								}
							} else if ( !(fabs(S[ os+(j*ss) ]*S[ os+(j*ss) ]*diagonal-1.0) <= 1.0e-14) ) {
								return EXIT_FAILURE;
							}
						}
						if ( am != (double)((N+1)*(N+1)) || (failed ? sc != 0.0 || !signbit(sc) : sc != 2.0/(double)(N+1)) || memcmp( before, AB, (size_t)(2*N)*sizeof(double) ) != 0 ) {
							return EXIT_FAILURE;
						}
						for ( j = 0; j < N+2; j++ ) {
							if ( ((ss < 0 && (j < os+(N-1)*ss || j > os)) || (ss > 0 && (j < os || j > os+(N-1)*ss))) && S[ j ] != 7.0 ) {
								return EXIT_FAILURE;
							}
						}
						count++;
						printf( "# c::dpbequ:N=%d:upper=%d:ndarray=%d:failed=%d\n", (int)N, upper, nd, failed );
						printf( "ok %d benchmark finished; 200 iterations; %.9f seconds\n", count, elapsed );
					}
				}
			}
		}
	}
	printf( "1..%d\n# total %d\n# pass  %d\n", count, count, count );
	return EXIT_SUCCESS;
}
